{
  "name": "rf_cal_load_band_params",
  "confidence": "medium",
  "docstring": "Loads and applies RF calibration parameters for the current band from the instance's calibration table into the active RF configuration, falling back to single-channel validation when the full-band flag is not set.",
  "subsystem": "rf",
  "var_renames": {
    "v1": "rf_inst_flags",
    "v2": "rf_inst",
    "v4": "rf_active_cal",
    "v5": "status",
    "v8": "band_cal_src",
    "v9": "cal_flags",
    "v10": "cal_packed_word",
    "v11": "cal_mode_bits",
    "v12": "cal_band_bits",
    "v13": "derived_cal_byte",
    "v33": "cal_word_source"
  },
  "struct_hints": [
    {
      "offset": 28,
      "meaning": "rf_inst field containing a pointer to the per-band RF calibration source structure"
    },
    {
      "offset": 84,
      "meaning": "rf_inst status flags; bit 0x2000 selects the full-band calibration load path"
    },
    {
      "offset": 96,
      "meaning": "rf_inst field cleared when applying band calibration"
    },
    {
      "offset": 0,
      "meaning": "band_cal_src uint16 calibration flag word"
    },
    {
      "offset": 4,
      "meaning": "band_cal_src uint8 field; bit 0 controls writing 8 to active RF table offset 48"
    },
    {
      "offset": 22,
      "meaning": "band_cal_src uint16 packed calibration word copied into the active RF table"
    },
    {
      "offset": 24,
      "meaning": "band_cal_src uint16 fallback word used when mode bits are not 0x300"
    },
    {
      "offset": 30,
      "meaning": "band_cal_src uint16 selected word used when mode bits equal 0x300"
    },
    {
      "offset": 4,
      "meaning": "rf_active_cal uint16 field receiving cal_packed_word >> 4"
    },
    {
      "offset": 6,
      "meaning": "rf_active_cal uint8 field receiving cal_packed_word low nibble"
    },
    {
      "offset": 7,
      "meaning": "rf_active_cal uint8 field derived from selected source uint16"
    },
    {
      "offset": 8,
      "meaning": "rf_active_cal uint8 derived calibration field based on source flag combinations"
    },
    {
      "offset": 36,
      "meaning": "rf_active_cal uint16 field copied from band_cal_src offset 16 when flag 0x100 is set"
    },
    {
      "offset": 42,
      "meaning": "rf_active_cal uint16 field copied from band_cal_src offset 12 when related 0x100/0x200 flags are set"
    }
  ]
}
